/bin/sh -c "python3 - <<'PY'
import os
needles={'evidence_index.txt':[], 'checklist.yaml':[], 'index.json':[]}
count=0
for base in ['/', '/root']:
    for root, dirs, files in os.walk(base, topdown=True):
        if root.startswith(('/proc','/sys','/dev','/run')):
            dirs[:] = []
            continue
        # prune repeated huge dirs
        dirs[:] = [d for d in dirs if d not in {'proc','sys','dev','run','node_modules','.git'}]
        for f in files:
            if f=='evidence_index.txt':
                needles['evidence_index.txt'].append(os.path.join(root,f))
            elif f=='checklist.yaml':
                needles['checklist.yaml'].append(os.path.join(root,f))
            elif f=='index.json' and root.endswith('/evidence'):
                needles['index.json'].append(os.path.join(root,f))
        count += 1
        if count % 5000 == 0:
            pass
for k,v in needles.items():
    print('\\n',k,len(v))
    for p in v[:120]:
        print(p)
